//! Parity tests for `gpt_sovits_text::zh_normalization` against golden fixtures
//! generated by `parity/zh_normalization/gen_fixtures.py`.

use gpt_sovits_text::zh_normalization::char_convert::{
  simplified_to_traditional, tranditional_to_simplified,
};
use gpt_sovits_text::zh_normalization::chronology::_time_num2str;
use gpt_sovits_text::zh_normalization::constants::{
  F2H_ASCII_LETTERS, F2H_DIGITS, F2H_PUNCTUATIONS, F2H_SPACE, H2F_ASCII_LETTERS, H2F_DIGITS,
  H2F_PUNCTUATIONS, H2F_SPACE, RE_NSW, translate, translate_str_keyed,
};
use gpt_sovits_text::zh_normalization::num::{
  _get_value, num2str, verbalize_cardinal, verbalize_digit,
};
use gpt_sovits_text::zh_normalization::phonecode::phone2str;
use gpt_sovits_text::zh_normalization::pyre::py_isspace;
use gpt_sovits_text::zh_normalization::{Error, TextNormalizer};
use serde_json::Value;

const NORMALIZE: &str = include_str!("fixtures/zh_normalization/normalize.jsonl");
const NORMALIZE_SENTENCE: &str = include_str!("fixtures/zh_normalization/normalize_sentence.jsonl");
const FUNCTIONS: &str = include_str!("fixtures/zh_normalization/functions.json");

/// Inputs whose Rust output is known to differ from Python. They must be
/// documented in `parity/README.md` and in `src/zh_normalization/mod.rs`;
/// currently there are none.
const KNOWN_MISMATCHES: &[&str] = &[];

/// Convert a Rust result to the fixture representation:
/// `{"o": output}` or `{"e": [type, arg]}`.
fn to_json<T: serde::Serialize>(r: Result<T, Error>) -> Value {
  match r {
    Ok(v) => serde_json::json!({ "o": v }),
    Err(Error::KeyError(k)) => serde_json::json!({ "e": ["KeyError", k] }),
    Err(Error::ValueError(m)) => serde_json::json!({ "e": ["ValueError", m] }),
  }
}

fn expected(case: &Value) -> Value {
  let mut v = case.clone();
  v.as_object_mut().unwrap().remove("i");
  v
}

/// Check every case; return (cases, mismatched inputs).
fn check_cases<'a, I, F>(cases: I, mut f: F) -> (usize, Vec<String>)
where
  I: IntoIterator<Item = &'a Value>,
  F: FnMut(&Value) -> Value,
{
  let mut n = 0;
  let mut mismatches = Vec::new();
  for case in cases {
    n += 1;
    let got = f(&case["i"]);
    let want = expected(case);
    if got != want {
      if mismatches.len() < 20 {
        eprintln!("mismatch for {}:\n  want {want}\n  got  {got}", case["i"]);
      }
      mismatches.push(
        case["i"]
          .as_str()
          .map_or_else(|| case["i"].to_string(), str::to_string),
      );
    }
  }
  (n, mismatches)
}

fn jsonl(src: &str) -> Vec<Value> {
  src
    .lines()
    .map(|l| serde_json::from_str(l).unwrap())
    .collect()
}

fn assert_parity(name: &str, (n, mismatches): (usize, Vec<String>)) {
  let unexpected: Vec<&String> = mismatches
    .iter()
    .filter(|m| !KNOWN_MISMATCHES.contains(&m.as_str()))
    .collect();
  eprintln!("{name}: {}/{n} exact matches", n - mismatches.len());
  assert!(
    unexpected.is_empty(),
    "{name}: {} unexpected mismatches",
    unexpected.len()
  );
  for known in KNOWN_MISMATCHES {
    assert!(
      mismatches.iter().any(|m| m == known),
      "{name}: known mismatch now matches: {known:?}"
    );
  }
}

#[test]
fn normalize_parity() {
  let tn = TextNormalizer::new();
  let cases = jsonl(NORMALIZE);
  assert!(cases.len() >= 6000);
  assert_parity(
    "normalize",
    check_cases(&cases, |i| to_json(tn.normalize(i.as_str().unwrap()))),
  );
}

#[test]
fn normalize_sentence_parity() {
  let tn = TextNormalizer::new();
  let cases = jsonl(NORMALIZE_SENTENCE);
  assert_parity(
    "normalize_sentence",
    check_cases(&cases, |i| {
      to_json(tn.normalize_sentence(i.as_str().unwrap()))
    }),
  );
}

fn functions() -> Value {
  serde_json::from_str(FUNCTIONS).unwrap()
}

fn str_cases<'a>(f: &'a Value, key: &str) -> &'a Vec<Value> {
  f[key].as_array().unwrap_or_else(|| panic!("missing {key}"))
}

#[test]
fn num_functions_parity() {
  let f = functions();
  let s = |v: &Value| v.as_str().unwrap().to_string();
  let (n, m) = check_cases(str_cases(&f, "num2str"), |i| to_json(num2str(&s(i))));
  assert_eq!(m, Vec::<String>::new(), "num2str ({n} cases)");
  let (n, m) = check_cases(str_cases(&f, "verbalize_cardinal"), |i| {
    to_json(verbalize_cardinal(&s(i)))
  });
  assert_eq!(m, Vec::<String>::new(), "verbalize_cardinal ({n} cases)");
  let (n, m) = check_cases(str_cases(&f, "verbalize_digit"), |i| {
    to_json(verbalize_digit(&s(i), false))
  });
  assert_eq!(m, Vec::<String>::new(), "verbalize_digit ({n} cases)");
  let (n, m) = check_cases(str_cases(&f, "verbalize_digit_alt_one"), |i| {
    to_json(verbalize_digit(&s(i), true))
  });
  assert_eq!(
    m,
    Vec::<String>::new(),
    "verbalize_digit alt_one ({n} cases)"
  );
  let (n, m) = check_cases(str_cases(&f, "_get_value"), |i| {
    to_json(_get_value(&s(i), true))
  });
  assert_eq!(m, Vec::<String>::new(), "_get_value ({n} cases)");
  let (n, m) = check_cases(str_cases(&f, "_time_num2str"), |i| {
    to_json(_time_num2str(&s(i)))
  });
  assert_eq!(m, Vec::<String>::new(), "_time_num2str ({n} cases)");
}

#[test]
fn phonecode_and_split_parity() {
  let f = functions();
  let s = |v: &Value| v.as_str().unwrap().to_string();
  let (n, m) = check_cases(str_cases(&f, "phone2str_mobile"), |i| {
    to_json(phone2str(&s(i), true))
  });
  assert_eq!(m, Vec::<String>::new(), "phone2str mobile ({n} cases)");
  let (n, m) = check_cases(str_cases(&f, "phone2str_landline"), |i| {
    to_json(phone2str(&s(i), false))
  });
  assert_eq!(m, Vec::<String>::new(), "phone2str landline ({n} cases)");
  let tn = TextNormalizer::new();
  let (n, m) = check_cases(str_cases(&f, "_split_en"), |i| {
    to_json(Ok(tn._split(&s(i), "en")))
  });
  assert_eq!(m, Vec::<String>::new(), "_split en ({n} cases)");
}

#[test]
fn char_convert_parity() {
  let f = functions();
  let s = |v: &Value| v.as_str().unwrap().to_string();
  for (key, conv) in [
    ("t2s_all", tranditional_to_simplified as fn(&str) -> String),
    ("s2t_all", simplified_to_traditional),
  ] {
    let case = &f[key];
    assert_eq!(conv(&s(&case["i"])), s(&case["o"]), "{key}");
  }
  let (n, m) = check_cases(str_cases(&f, "t2s_random"), |i| {
    to_json(Ok(tranditional_to_simplified(&s(i))))
  });
  assert_eq!(m, Vec::<String>::new(), "t2s random ({n} cases)");
  let (n, m) = check_cases(str_cases(&f, "s2t_random"), |i| {
    to_json(Ok(simplified_to_traditional(&s(i))))
  });
  assert_eq!(m, Vec::<String>::new(), "s2t random ({n} cases)");
}

#[test]
fn constants_parity() {
  let f = functions();
  let s = |v: &Value| v.as_str().unwrap().to_string();
  let (n, m) = check_cases(str_cases(&f, "re_nsw_findall"), |i| {
    to_json(Ok(RE_NSW.findall(&s(i))))
  });
  assert_eq!(m, Vec::<String>::new(), "RE_NSW.findall ({n} cases)");
  let (n, m) = check_cases(str_cases(&f, "translate"), |i| {
    let t = s(i);
    to_json(Ok(serde_json::json!({
      "F2H_ASCII_LETTERS": translate(&t, &F2H_ASCII_LETTERS),
      "H2F_ASCII_LETTERS": translate(&t, &H2F_ASCII_LETTERS),
      "F2H_DIGITS": translate(&t, &F2H_DIGITS),
      "H2F_DIGITS": translate(&t, &H2F_DIGITS),
      "F2H_PUNCTUATIONS": translate(&t, &F2H_PUNCTUATIONS),
      "H2F_PUNCTUATIONS": translate(&t, &H2F_PUNCTUATIONS),
      "F2H_SPACE": translate_str_keyed(&t, &F2H_SPACE),
      "H2F_SPACE": translate_str_keyed(&t, &H2F_SPACE),
    })))
  });
  assert_eq!(m, Vec::<String>::new(), "translation tables ({n} cases)");
}

#[test]
fn isspace_parity() {
  let f = functions();
  let want: Vec<u32> = str_cases(&f, "isspace")
    .iter()
    .map(|v| v.as_u64().unwrap() as u32)
    .collect();
  let got: Vec<u32> = (0..=0x10FFFFu32)
    .filter_map(char::from_u32)
    .filter(|c| py_isspace(*c))
    .map(|c| c as u32)
    .collect();
  assert_eq!(got, want);
}
